import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Epic: Monetization","description":"","frontmatter":{},"headers":[],"relativePath":"sovereign-edge/epics/monetization.md","filePath":"sovereign-edge/epics/monetization.md"}'),i={name:"sovereign-edge/epics/monetization.md"};function r(s,e,l,c,p,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="epic-monetization" tabindex="-1">Epic: Monetization <a class="header-anchor" href="#epic-monetization" aria-label="Permalink to &quot;Epic: Monetization&quot;">​</a></h1><blockquote><p>Paid connectors — platform in-app purchase on mobile, direct sale on desktop. The core app and baseline connectors are free forever and are never gated by anything in this epic.</p></blockquote><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>📋 Planned</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Mirrors <code>sovereign</code>&#39;s own entitlement-based plugin monetization (RFC 0003 in that repo) at the concept level — a connector author declares pricing, an entitlement unlocks it — but the purchase rail diverges by platform because mobile app stores require their own in-app purchase system for unlocking digital features inside a binary, which <code>sovereign</code>&#39;s self-hosted web platform never had to deal with.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="📋-6-1-—-entitlement-model" tabindex="-1">📋 6.1 — Entitlement model <a class="header-anchor" href="#📋-6-1-—-entitlement-model" aria-label="Permalink to &quot;📋 6.1 — Entitlement model&quot;">​</a></h4><p><strong>Goal:</strong> A platform-agnostic notion of &quot;this connector is unlocked for this user,&quot; independent of which purchase rail granted it.</p><p><strong>Deliverables:</strong></p><ul><li>An entitlement record/token concept a paid connector checks before it&#39;s usable, decoupled from the purchase mechanism itself (mirrors <code>sovereign</code>&#39;s signed-entitlement pattern, adapted for a mobile/desktop client instead of a server).</li></ul><p><strong>Dependencies:</strong> Connector Framework epic (2.1, <code>pricing</code> field).</p><p><strong>Review checklist:</strong></p><ul><li>A connector marked paid is unusable without a valid entitlement, on any platform.</li></ul><hr><h4 id="📋-6-2-—-mobile-in-app-purchase-integration" tabindex="-1">📋 6.2 — Mobile in-app purchase integration <a class="header-anchor" href="#📋-6-2-—-mobile-in-app-purchase-integration" aria-label="Permalink to &quot;📋 6.2 — Mobile in-app purchase integration&quot;">​</a></h4><p><strong>Goal:</strong> Unlock paid connectors via Apple/Google&#39;s required IAP systems.</p><p><strong>Deliverables:</strong></p><ul><li>StoreKit (iOS) and Google Play Billing (Android) integration.</li><li>Purchase → entitlement-grant flow feeding into the Task 6.1 model.</li></ul><p><strong>Dependencies:</strong> Task 6.1.</p><p><strong>Review checklist:</strong></p><ul><li>A real sandbox purchase on both platforms results in the corresponding connector becoming usable, and a refund/revocation removes access.</li></ul><hr><h4 id="📋-6-3-—-desktop-direct-sale-flow" tabindex="-1">📋 6.3 — Desktop direct-sale flow <a class="header-anchor" href="#📋-6-3-—-desktop-direct-sale-flow" aria-label="Permalink to &quot;📋 6.3 — Desktop direct-sale flow&quot;">​</a></h4><p><strong>Goal:</strong> Sell paid connectors directly on desktop, where there&#39;s no app- store payment requirement.</p><p><strong>Deliverables:</strong></p><ul><li>A direct purchase flow (payment provider TBD) granting the same entitlement model as Task 6.1, without an IAP intermediary.</li></ul><p><strong>Dependencies:</strong> Task 6.1, Desktop App epic.</p><p><strong>Review checklist:</strong></p><ul><li>A desktop purchase and a mobile purchase of the same connector both result in the identical entitlement check passing.</li></ul><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../research/0001-concept-and-connector-architecture.html">research 0001</a></li><li><a href="./connector-store-sdk.html">Connector Store &amp; SDK</a></li></ul>',32)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
